const inputClass = "h-10 rounded-xl border border-white/10 bg-white/[0.025] px-3 text-sm text-white outline-none focus:border-[#F5B800]/70";
const currentDate = new Date().toISOString().slice(0, 10);
const currentMonthStart = `${currentDate.slice(0, 7)}-01`;
const number = (value: unknown, digits = 2) => new Intl.NumberFormat("ar", { maximumFractionDigits: digits }).format(Number(value ?? 0));
const reportMetrics = REPORT_METRICS;
const paymentProviderLabels = REPORT_PAYMENT_METHOD_LABELS;

type FinancialSummary = { invoiced: number; collected: number; outstanding: number; energyKwh: number; expenseTotal: number; operatingProfit: number };
type FinancialReport = {
  range: { startDate: string; endDate: string };
  summary: FinancialSummary;
  collectors: { name: string; count: number; amount: number }[];
  topDebtors: { subscriber: string; invoiceNo: string; balanceDue: number; dueDate?: Date; branchName?: string }[];
  scope?: { branchCount: number };
  branchSummaries?: { siteId: number; branchName: string; invoiced: number; collected: number; outstanding: number; energyKwh: number; expenseTotal: number; operatingProfit: number }[];
  paymentDetails?: { siteId?: number; paymentNo: string; amount: number; paymentMethod: string; paidAt: Date; transferFromAccount?: string | null; transferFromType?: string | null; transferToAccount?: string | null; transferToType?: string | null }[];
};

type ReportSection = "summary" | "branches" | "collectors" | "payments";
const reportSectionLabels: Record<ReportSection, string> = { summary: "الملخص المالي", branches: "تفصيل الأفرع", collectors: "أداء المحصلين", payments: "تفاصيل الدفعات والتحويلات" };
function financialRows(report: FinancialReport, scopeName: string, sections: ReportSection[] = ["summary", "branches", "collectors", "payments"]) {
  const branchRows = report.branchSummaries ?? [];
  const paymentRows = (report.paymentDetails ?? []).map((payment) => [payment.paymentNo, payment.amount, payment.paymentMethod, payment.transferFromAccount ?? "—", payment.transferFromType ?? "—", payment.transferToAccount ?? "—", payment.transferToType ?? "—"]);
  return [["تقرير PowerHub المالي", ""], ["النطاق", scopeName], ["بداية الفترة", report.range.startDate], ["نهاية الفترة", report.range.endDate], ...(sections.includes("summary") ? [[], ["المؤشر", "القيمة"], ["إجمالي الفوترة", report.summary.invoiced], ["إجمالي التحصيل", report.summary.collected], ["الأرصدة المستحقة", report.summary.outstanding], ["الاستهلاك kWh", report.summary.energyKwh], ["المصروفات", report.summary.expenseTotal], ["صافي التدفق التشغيلي", report.summary.operatingProfit]] : []), ...(sections.includes("branches") && branchRows.length ? [[], ["تفصيل الأفرع", "الفوترة", "التحصيل", "الأرصدة المستحقة", "المصروفات", "صافي التدفق التشغيلي"], ...branchRows.map((branch) => [branch.branchName, branch.invoiced, branch.collected, branch.outstanding, branch.expenseTotal, branch.operatingProfit])] : []), ...(sections.includes("collectors") ? [[], ["المحصل", "عدد الدفعات", "قيمة التحصيل"], ...(report.collectors ?? []).map((row) => [row.name, row.count, row.amount])] : []), ...(sections.includes("payments") && paymentRows.length ? [[], ["رقم الإيصال", "المبلغ", "الطريقة", "الحساب المحوِّل", "نوعه", "الحساب المستقبِل", "نوعه"], ...paymentRows] : [])];
}

function triggerDownload(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = filename; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url);
}

function readBase64(file: File) { return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(new Error("تعذر قراءة ملف الشعار.")); reader.onload = () => resolve(String(reader.result).split(",")[1] ?? ""); reader.readAsDataURL(file); }); }
function difference(value: number, baseline: number) { const amount = value - baseline; const percent = baseline === 0 ? (value === 0 ? 0 : null) : (amount / Math.abs(baseline)) * 100; return { amount, percent }; }

export default function ReportsPage() {
  const { isAuthenticated, loading, user } = useAuth();
  const sitesQuery = trpc.powerhub.sites.list.useQuery(undefined, { enabled: isAuthenticated });
  const { branchId, setBranchId } = useBranchFilter(sitesQuery.data);
  const [scope, setScope] = useState<"branch" | "all">("branch");
  const [startDate, setStartDate] = useState(currentMonthStart);
  const [endDate, setEndDate] = useState(currentDate);
  const [reportPaymentProvider, setReportPaymentProvider] = useState("all");
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewZoom, setPreviewZoom] = useState(100);
  const [selectedReportSections, setSelectedReportSections] = useState<ReportSection[]>(["summary", "branches", "collectors", "payments"]);
  const [reportKind, setReportKind] = useState<"daily" | "monthly" | "custom">("monthly");
  const [comparisonMode, setComparisonMode] = useState<"period" | "branch">("period");
  const [comparisonSiteId, setComparisonSiteId] = useState<number | null>(null);
  const [comparisonStartDate, setComparisonStartDate] = useState(currentMonthStart);
  const [comparisonEndDate, setComparisonEndDate] = useState(currentDate);
  const [companyNameDraft, setCompanyNameDraft] = useState("");
  const [isOnline, setIsOnline] = useState(() => typeof navigator === "undefined" ? true : navigator.onLine);
  const [cachedSnapshot, setCachedSnapshot] = useState<CachedReportSnapshot | null>(null);
  const [pendingPaymentDrafts, setPendingPaymentDrafts] = useState<QueuedOfflineWork[]>([]);
  const pdfRef = useRef<HTMLDivElement>(null);
  const accessQuery = trpc.powerhub.staff.allBranchAccess.useQuery({ siteId: branchId ?? 0 }, { enabled: Boolean(branchId && isAuthenticated) });
  const roleQuery = trpc.powerhub.staff.myAccess.useQuery({ siteId: branchId ?? 0 }, { enabled: Boolean(branchId && isAuthenticated) });
  const canUseAllBranches = accessQuery.data?.isGlobal === true && (sitesQuery.data?.length ?? 0) > 1;
  const canCompareBranches = canUseAllBranches;
  const canManageBranding = roleQuery.data?.role === "owner";
  const canReadFinancialReport = ["owner", "manager", "accountant", "viewer"].includes(roleQuery.data?.role ?? "");
  const baseEnabled = Boolean(branchId && isAuthenticated && startDate <= endDate);
  const branchReportQuery = trpc.powerhub.reports.range.useQuery({ siteId: branchId ?? 0, startDate, endDate }, { enabled: baseEnabled && scope === "branch" });
  const allReportQuery = trpc.powerhub.reports.allBranchesRange.useQuery({ siteId: branchId ?? 0, startDate, endDate }, { enabled: baseEnabled && scope === "all" && canUseAllBranches });
  const activeQuery = scope === "all" ? allReportQuery : branchReportQuery;
  const reportAccessDenied = [activeQuery.error?.data?.code, roleQuery.error?.data?.code, accessQuery.error?.data?.code]
    .some((code) => code === "FORBIDDEN" || code === "UNAUTHORIZED");
  const reportRevisionQuery = trpc.powerhub.dashboard.deltaRevision.useQuery(
    { siteId: branchId ?? 0, scope },
    {
      enabled: Boolean(baseEnabled && canReadFinancialReport && !reportAccessDenied && (scope !== "all" || canUseAllBranches)),
      staleTime: 0,
      refetchInterval: false,
      refetchOnReconnect: false,
      refetchOnWindowFocus: false,
    },
  );
  // React Query can retain previous data after a failed refetch. Only a
  // successful, current-scope read may refresh the local financial snapshot.
  const liveReport = !reportAccessDenied && hasAuthoritativeServerRead(activeQuery)
    ? activeQuery.data as FinancialReport | undefined
    : undefined;
  const snapshotScope = user?.id && branchId ? { userId: user.id, siteId: branchId, scope, startDate, endDate } as const : null;
  const cachedSnapshotForCurrentScope = snapshotScope ? getUsableReportSnapshot(cachedSnapshot, snapshotScope, {
    authorizationDenied: reportAccessDenied,
    accessAllowed: Boolean(user?.id && branchId && (scope !== "all" || canUseAllBranches)),
  }) : undefined;
  const report = reportAccessDenied ? undefined : liveReport ?? cachedSnapshotForCurrentScope?.report as FinancialReport | undefined;
  const usingCachedReport = !liveReport && Boolean(cachedSnapshotForCurrentScope);
  const scopeName = scope === "all" ? `جميع الأفرع (${report?.scope?.branchCount ?? sitesQuery.data?.length ?? 0})` : sitesQuery.data?.find((site) => site.id === branchId)?.name ?? "الفرع المحدد";
  const alternateBranchId = comparisonSiteId ?? (sitesQuery.data ?? []).find((site) => site.id !== branchId)?.id ?? null;
  const comparisonPeriodEnabled = baseEnabled && comparisonMode === "period" && comparisonStartDate <= comparisonEndDate;
  const comparisonBranchEnabled = Boolean(isAuthenticated && comparisonMode === "branch" && canCompareBranches && alternateBranchId && startDate <= endDate);
  const comparisonPeriodBranchQuery = trpc.powerhub.reports.range.useQuery({ siteId: branchId ?? 0, startDate: comparisonStartDate, endDate: comparisonEndDate }, { enabled: comparisonPeriodEnabled && scope === "branch" });
  const comparisonPeriodAllQuery = trpc.powerhub.reports.allBranchesRange.useQuery({ siteId: branchId ?? 0, startDate: comparisonStartDate, endDate: comparisonEndDate }, { enabled: comparisonPeriodEnabled && scope === "all" && canUseAllBranches });
  const comparisonBranchQuery = trpc.powerhub.reports.range.useQuery({ siteId: alternateBranchId ?? 0, startDate, endDate }, { enabled: comparisonBranchEnabled });
  const comparisonActiveQuery = comparisonMode === "branch" ? comparisonBranchQuery
    : scope === "all" ? comparisonPeriodAllQuery : comparisonPeriodBranchQuery;
  const comparisonReport = hasAuthoritativeServerRead(comparisonActiveQuery)
    ? comparisonActiveQuery.data as FinancialReport | undefined
    : undefined;
  const comparisonIsFetching = comparisonActiveQuery.isFetching;
  const comparisonBranchRevisionEnabled = comparisonBranchEnabled && canReadFinancialReport;
  const comparisonBranchRevisionQuery = trpc.powerhub.dashboard.deltaRevision.useQuery(
    { siteId: alternateBranchId ?? 0, scope: "branch" },
    { enabled: comparisonBranchRevisionEnabled, staleTime: 0, refetchInterval: false, refetchOnReconnect: false, refetchOnWindowFocus: false },
  );
  const lastReportRevisions = useRef<Map<string, string>>(new Map());
  const lastComparisonReportRevisions = useRef<Map<string, string>>(new Map());
  const checkFinancialReportRevision = useCallback(async () => {
    await reportRevisionQuery.refetch();
  }, [reportRevisionQuery.refetch]);
  useAdaptiveDeltaRefresh({
    scopeKey: "financial-report:" + String(user?.id ?? "unknown") + ":" + String(branchId ?? 0) + ":" + scope,
    enabled: Boolean(baseEnabled && canReadFinancialReport && !reportAccessDenied && (scope !== "all" || canUseAllBranches)),
    check: checkFinancialReportRevision,
    realtimeTopic: reportRevisionQuery.data?.realtimeTopic,
  });
  const checkComparisonBranchRevision = useCallback(async () => {
    await comparisonBranchRevisionQuery.refetch();
  }, [comparisonBranchRevisionQuery.refetch]);
  useAdaptiveDeltaRefresh({
    scopeKey: "financial-report-comparison:" + String(user?.id ?? "unknown") + ":" + String(alternateBranchId ?? 0),
    enabled: comparisonBranchRevisionEnabled,
    check: checkComparisonBranchRevision,
    realtimeTopic: comparisonBranchRevisionQuery.data?.realtimeTopic,
  });
  const comparisonScopeName = comparisonMode === "branch" ? sitesQuery.data?.find((site) => site.id === alternateBranchId)?.name ?? "الفرع المقارن" : `${scopeName} — ${comparisonStartDate} إلى ${comparisonEndDate}`;
  const brandingQuery = trpc.powerhub.reportBranding.get.useQuery({ siteId: branchId ?? 0 }, { enabled: Boolean(branchId && isAuthenticated) });
  const brandingMutation = trpc.powerhub.reportBranding.update.useMutation({ onSuccess: async () => { await brandingQuery.refetch(); toast.success("تم تحديث هوية التقرير الرسمية."); }, onError: (error) => toast.error(error.message) });


  useEffect(() => {
    const revision = reportRevisionQuery.data?.revisions?.financialReport;
    if (!user?.id || !branchId || !revision || !baseEnabled) return;
    const key = [user.id, branchId, scope].join(":");
    const previous = lastReportRevisions.current.get(key);
    lastReportRevisions.current.delete(key);
    lastReportRevisions.current.set(key, revision);
    while (lastReportRevisions.current.size > 32) {
      const oldest = lastReportRevisions.current.keys().next().value;
      if (oldest === undefined) break;
      lastReportRevisions.current.delete(oldest);
    }
    if (previous && previous !== revision) {
      // Re-run the exact server query for the active filter set; never rebuild
      // a financial report from partial Delta rows or a local snapshot.
      void activeQuery.refetch();
      if (comparisonMode === "period") void comparisonActiveQuery.refetch();
    }
  }, [
    reportRevisionQuery.dataUpdatedAt, reportRevisionQuery.data?.revisions?.financialReport,
    user?.id, branchId, scope, baseEnabled, comparisonMode,
    activeQuery.refetch, comparisonActiveQuery.refetch,
  ]);
  useEffect(() => {
    const revision = comparisonBranchRevisionQuery.data?.revisions?.financialReport;
    if (!user?.id || !alternateBranchId || !revision || !comparisonBranchRevisionEnabled) return;
    const key = [user.id, alternateBranchId].join(":");
    const previous = lastComparisonReportRevisions.current.get(key);
    lastComparisonReportRevisions.current.set(key, revision);
    while (lastComparisonReportRevisions.current.size > 32) {
      const oldest = lastComparisonReportRevisions.current.keys().next().value;
      if (oldest === undefined) break;
      lastComparisonReportRevisions.current.delete(oldest);
    }
    if (previous && previous !== revision) void comparisonBranchQuery.refetch();
  }, [
    comparisonBranchRevisionQuery.dataUpdatedAt,
    comparisonBranchRevisionQuery.data?.revisions?.financialReport,
    user?.id, alternateBranchId, comparisonBranchRevisionEnabled, comparisonBranchQuery.refetch,
  ]);

  useEffect(() => { if (scope === "all" && !canUseAllBranches) setScope("branch"); }, [canUseAllBranches, scope]);
  useEffect(() => { if (comparisonMode === "branch" && !canCompareBranches) setComparisonMode("period"); }, [canCompareBranches, comparisonMode]);
  useEffect(() => { const candidate = (sitesQuery.data ?? []).find((site) => site.id !== branchId)?.id ?? null; if (candidate && (comparisonSiteId === null || comparisonSiteId === branchId)) setComparisonSiteId(candidate); }, [branchId, comparisonSiteId, sitesQuery.data]);
  useEffect(() => { if (brandingQuery.data?.companyName) setCompanyNameDraft(brandingQuery.data.companyName); }, [brandingQuery.data?.companyName]);
  useEffect(() => {
    const online = () => setIsOnline(true); const offline = () => setIsOnline(false);
    window.addEventListener("online", online); window.addEventListener("offline", offline);
    return () => { window.removeEventListener("online", online); window.removeEventListener("offline", offline); };
  }, []);
  useEffect(() => {
    if (!user?.id || !branchId) return;
    const input = { userId: user.id, siteId: branchId, scope, startDate, endDate } as const;
    if (liveReport) { void saveReportSnapshot({ ...input, report: createOfflineReportSnapshotPayload(liveReport) }).then(setCachedSnapshot).catch(() => undefined); }
    else { void loadReportSnapshot(input).then((snapshot) => setCachedSnapshot(snapshot ?? null)).catch(() => setCachedSnapshot(null)); }
    void listOfflineWork({ userId: user.id, siteId: branchId }).then((items) => setPendingPaymentDrafts(items.filter((item) => item.kind === "payment_create" && item.status !== "applied"))).catch(() => setPendingPaymentDrafts([]));
  }, [branchId, endDate, liveReport, scope, startDate, user?.id]);

  const clearReportFilters = () => { setScope("branch"); setStartDate(currentMonthStart); setEndDate(currentDate); setReportPaymentProvider("all"); setReportKind("monthly"); };
  const reportFilterLabel = reportPaymentProvider === "all" ? "كل طرق الدفع" : (paymentProviderLabels[reportPaymentProvider] ?? reportPaymentProvider);
  const filteredExportReport = report ? { ...report, paymentDetails: (report.paymentDetails ?? []).filter((payment) => reportPaymentProvider === "all" || payment.paymentMethod === reportPaymentProvider) } : null;
  const printReport = () => { if (!liveReport || usingCachedReport || reportAccessDenied || !pdfRef.current) { toast.error("لا يمكن طباعة لقطة مالية محلية كتقرير رسمي؛ يلزم تحقق خادمي ناجح وحديث."); return; } const printWindow = window.open("", "_blank", "width=1000,height=800"); if (!printWindow) return toast.error("تعذر فتح نافذة الطباعة. اسمح بالنوافذ المنبثقة ثم حاول مجدداً."); printWindow.document.write(`<html dir="rtl"><head><title>تقرير PowerHub</title><style>body{font-family:Arial,sans-serif;margin:24px;color:#0D1117}img{max-width:100px}table{border-collapse:collapse;width:100%}td,th{padding:8px;border:1px solid #ddd} @media print{button{display:none}}</style></head><body></body></html>`); printWindow.document.close(); printWindow.document.body.appendChild(pdfRef.current.cloneNode(true)); printWindow.focus(); setTimeout(() => { printWindow.print(); printWindow.close(); }, 250); };
  const downloadCsv = () => { if (!liveReport || usingCachedReport || reportAccessDenied) return toast.error("التصدير الرسمي يتطلب تحققًا خادميًا ناجحًا وحديثًا لنفس الفلاتر."); const rows = financialRows(filteredExportReport ?? liveReport, scopeName, selectedReportSections); rows.splice(1, 0, ["طريقة الدفع", reportFilterLabel]); const csv = "\uFEFF" + rows.map((row) => row.map((cell) => `"${String(cell ?? "").replaceAll('"', '""')}"`).join(",")).join("\n"); triggerDownload(new Blob([csv], { type: "text/csv;charset=utf-8" }), `powerhub-financial-${scope === "all" ? "all-branches" : `branch-${branchId}`}-${startDate}_to_${endDate}-${reportPaymentProvider}.csv`); toast.success("تم تصدير التقرير المالي المفلتر بصيغة CSV."); };
  const downloadExcel = async () => { if (!liveReport || usingCachedReport || reportAccessDenied) return toast.error("التصدير الرسمي يتطلب تحققًا خادميًا ناجحًا وحديثًا لنفس الفلاتر."); try { const { default: ExcelJS } = await loadExcelJS(); const workbook = new ExcelJS.Workbook(); workbook.creator = "PowerHub"; workbook.created = new Date(); const sheet = workbook.addWorksheet("التقرير المالي", { views: [{ rightToLeft: true }] }); sheet.addRow(["معايير التصفية", `الفترة: ${formatReportPeriod(startDate, endDate)} | طريقة الدفع: ${reportFilterLabel}`]); financialRows(filteredExportReport ?? liveReport, scopeName, selectedReportSections).forEach((row) => sheet.addRow(row)); sheet.columns = [{ width: 30 }, { width: 22 }, { width: 18 }, { width: 18 }, { width: 18 }, { width: 18 }]; [1, 6].forEach((rowNumber) => { const row = sheet.getRow(rowNumber); row.font = { bold: true, color: { argb: "FFFFFFFF" } }; row.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF0D1117" } }; row.height = 24; }); for (let index = 1; index <= sheet.rowCount; index += 1) sheet.getRow(index).alignment = { vertical: "middle", horizontal: "right" }; const buffer = await workbook.xlsx.writeBuffer(); triggerDownload(new Blob([buffer], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }), `powerhub-financial-${scope === "all" ? "all-branches" : `branch-${branchId}`}-${startDate}_to_${endDate}.xlsx`); toast.success("تم تجهيز تقرير Excel المالي."); } catch { toast.error("تعذر تجهيز ملف Excel. حاول مرة أخرى."); } };
  const downloadPdf = async () => { if (!pdfRef.current || !liveReport || usingCachedReport || reportAccessDenied) return toast.error("تصدير PDF الرسمي يتطلب تحققًا خادميًا ناجحًا وحديثًا لنفس الفلاتر."); try { await downloadReportHtmlAsPdf(pdfRef.current, "تقرير-مالي-" + startDate + ".pdf", { title: "تقرير مالي رسمي من PowerHub" }); toast.success("تم تصدير التقرير بصيغة PDF."); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر إنشاء ملف PDF."); } };
  const saveCompanyName = () => { if (!branchId || !companyNameDraft.trim()) return toast.error("أدخل اسم الشركة أولاً."); brandingMutation.mutate({ siteId: branchId, companyName: companyNameDraft.trim() }); };
  const selectLogo = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file) return; if (!(["image/png", "image/jpeg", "image/webp"] as string[]).includes(file.type)) return toast.error("استخدم شعار PNG أو JPG أو WebP فقط."); if (file.size > 3 * 1024 * 1024) return toast.error("يجب ألا يتجاوز حجم الشعار 3 ميغابايت."); try { const logoData = await readBase64(file); brandingMutation.mutate({ siteId: branchId!, companyName: companyNameDraft.trim() || undefined, logoData, logoMime: file.type as "image/png" | "image/jpeg" | "image/webp" }); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر تجهيز الشعار."); } };

  if (loading) return <DashboardLayout><div className="grid min-h-[60vh] place-items-center"><Loader2 className="h-7 w-7 animate-spin text-[#F5B800]" /></div></DashboardLayout>;
  if (!isAuthenticated) return <DashboardLayout><div className="mx-auto mt-12 max-w-xl rounded-[28px] border border-[#F5B800]/20 bg-[#111823] p-8 text-center shadow-panel"><FileBarChart2 className="mx-auto h-8 w-8 text-[#F5B800]" /><h1 className="mt-5 text-xl font-extrabold text-white">سجّل الدخول لعرض التقارير</h1><Button onClick={() => startLogin()} className="mt-6 bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]">تسجيل الدخول</Button></div></DashboardLayout>;

  const summary = report?.summary; const branchSummaries = report?.branchSummaries ?? [];
  const filteredReportPayments = (report?.paymentDetails ?? []).filter((payment) => reportPaymentProvider === "all" || payment.paymentMethod === reportPaymentProvider);
  const paymentSummary = Object.entries(filteredReportPayments.reduce<Record<string, number>>((totals, payment) => { totals[payment.paymentMethod] = (totals[payment.paymentMethod] ?? 0) + payment.amount; return totals; }, {}));
  const collectionRate = summary?.invoiced ? (summary.collected / summary.invoiced) * 100 : 0;
  const pendingPaymentDraftTotal = pendingPaymentDrafts.reduce((total, item) => total + Number((item.payload as { amount?: number }).amount ?? 0), 0);
  const reportKindLabel = reportKind === "daily" ? "التقرير اليومي التنفيذي" : reportKind === "monthly" ? "التقرير الشهري التنفيذي" : "تقرير مالي مخصص";
  const setDailyReport = () => { setReportKind("daily"); setStartDate(currentDate); setEndDate(currentDate); };
  const setMonthlyReport = () => { setReportKind("monthly"); setStartDate(currentMonthStart); setEndDate(currentDate); };
  const applyRangePreset = (value: string) => { const today = new Date(); const iso = (date: Date) => date.toISOString().slice(0, 10); if (value === "today") return setDailyReport(); if (value === "month") return setMonthlyReport(); if (value === "last30") { const start = new Date(today); start.setDate(start.getDate() - 29); setReportKind("custom"); setStartDate(iso(start)); setEndDate(currentDate); return; } if (value === "quarter") { const start = new Date(Date.UTC(today.getUTCFullYear(), Math.floor(today.getUTCMonth() / 3) * 3, 1)); setReportKind("custom"); setStartDate(iso(start)); setEndDate(currentDate); return; } setReportKind("custom"); };
  return <DashboardLayout><div className="space-y-6 pb-12"><header className="flex flex-col gap-4 rounded-[24px] border border-white/8 bg-[#111823]/80 p-5 shadow-panel sm:flex-row sm:items-center sm:justify-between"><div><div className="flex items-center gap-2 text-sm font-bold text-[#F5B800]"><FileBarChart2 className="h-4 w-4" />الرؤية والتحليل</div><h1 className="mt-1 text-2xl font-extrabold text-white">التقارير المالية</h1><p className="mt-2 text-sm text-slate-400">تقرير للفرع أو لكل الأفرع، ومقارنة أداء واضحة، وتصدير رسمي يحمل هوية شركتك.</p></div><div className="flex flex-wrap gap-2"><select aria-label="فلتر الفرع الموحد" value={scope === "all" ? "all" : String(branchId ?? "")} onChange={(event) => { const value = event.target.value; if (value === "all") setScope("all"); else { setBranchId(Number(value)); setScope("branch"); } }} className={inputClass}>{canUseAllBranches && <option className="bg-[#111823]" value="all">جميع الأفرع (مجمّع)</option>}{(sitesQuery.data ?? []).map((site) => <option className="bg-[#111823]" value={site.id} key={site.id}>{site.name}</option>)}</select><input aria-label="تاريخ بداية التقرير" type="date" value={startDate} max={endDate} onChange={(event) => setStartDate(event.target.value)} className={inputClass} dir="ltr" /><input aria-label="تاريخ نهاية التقرير" type="date" value={endDate} min={startDate} onChange={(event) => setEndDate(event.target.value)} className={inputClass} dir="ltr" /><select aria-label="فلتر طريقة الدفع في التقرير" value={reportPaymentProvider} onChange={(event) => setReportPaymentProvider(event.target.value)} className={inputClass}>{REPORT_PAYMENT_METHOD_OPTIONS.map((option) => <option className="bg-[#111823]" value={option.value} key={option.value}>{option.label}</option>)}</select><Button onClick={downloadCsv} disabled={!liveReport || startDate > endDate} className="bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]"><Download className="ml-2 h-4 w-4" />CSV</Button><Button onClick={() => void downloadExcel()} disabled={!liveReport || startDate > endDate} variant="outline" className="border-white/10 text-white hover:bg-white/5 hover:text-white"><FileSpreadsheet className="ml-2 h-4 w-4" />Excel</Button><Button onClick={clearReportFilters} disabled={scope === "branch" && startDate === currentMonthStart && endDate === currentDate && reportPaymentProvider === "all"} variant="outline" className="border-white/10 text-white hover:bg-white/5 hover:text-white">مسح الفلاتر</Button><Button onClick={() => setPreviewOpen(true)} disabled={!liveReport} variant="outline" className="border-sky-400/35 text-sky-200 hover:bg-sky-400/10 hover:text-sky-100">طباعة</Button><Button onClick={() => setPreviewOpen(true)} disabled={!liveReport} variant="outline" className="border-[#F5B800]/40 text-[#F5B800] hover:bg-[#F5B800]/10 hover:text-[#ffd23f]"><FileText className="ml-2 h-4 w-4" />PDF رسمي</Button></div></header>
    <ExecutiveReportToolbar kind={reportKind} label={reportKindLabel} scopeName={scopeName} summary={summary} collectionRate={collectionRate} onDaily={setDailyReport} onMonthly={setMonthlyReport} onCustom={() => setReportKind("custom")} />
    <ReportRangePresets onSelect={applyRangePreset} />
    <FinancialAccessScope role={roleQuery.data?.role} global={canUseAllBranches} />
    <Card className="border-[#F5B800]/18 bg-[#F5B800]/[.035]"><CardContent className="flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-center gap-3"><Layers3 className="h-5 w-5 text-[#F5B800]" /><div><p className="font-bold text-white">نطاق التقرير: {scopeName}</p><p className="mt-1 text-xs text-slate-400">فلتر الفرع محفوظ ويُستخدم تلقائياً في صفحات التشغيل التي تدعمه.</p></div></div>{activeQuery.isFetching && <span className="text-xs font-bold text-[#F5B800]">جارٍ تحديث التقرير…</span>}</CardContent></Card>
    {usingCachedReport ? <Card className="border-amber-400/25 bg-amber-400/[.06]"><CardContent className="flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-start gap-3"><CloudOff className="mt-0.5 h-5 w-5 text-amber-200" /><div><p className="font-bold text-amber-100">أنت تعرض لقطة محلية للقراءة فقط</p><p className="mt-1 text-xs leading-5 text-amber-100/75">آخر مزامنة: {cachedSnapshot ? formatReportDate(cachedSnapshot.savedAt) : "—"}. لا يمكن اعتماد هذه الأرقام أو طباعتها أو تصديرها كتقرير رسمي حتى عودة الاتصال.</p></div></div><Badge className="bg-amber-400/10 text-amber-100">دون اتصال</Badge></CardContent></Card> : null}
    {pendingPaymentDrafts.length ? <Card className="border-sky-400/20 bg-sky-400/[.04]"><CardContent className="flex flex-wrap items-center justify-between gap-3 p-4"><div><p className="font-bold text-sky-100">مسودات تحصيل غير متزامنة لا تدخل في التقرير</p><p className="mt-1 text-xs leading-5 text-sky-100/75">يوجد {pendingPaymentDrafts.length} تحصيل معلق بقيمة تقديرية {number(pendingPaymentDraftTotal)}. ستنعكس في التقارير فقط بعد قبول الخادم للمزامنة.</p></div><Button size="sm" onClick={() => window.location.assign("/offline-sync")} variant="outline" className="border-sky-400/35 text-sky-100 hover:bg-sky-400/10"><RefreshCw className="ml-1.5 h-3.5 w-3.5" />فتح مركز المزامنة</Button></CardContent></Card> : null}
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{ label: "إجمالي الفوترة", value: summary?.invoiced }, { label: "إجمالي التحصيل", value: summary?.collected }, { label: "الأرصدة المستحقة", value: summary?.outstanding }, { label: "صافي التدفق التشغيلي", value: summary?.operatingProfit }].map((item) => <Card className="border-white/8 bg-[#111823] shadow-panel" key={item.label}><CardContent className="p-5"><p className="text-sm text-slate-400">{item.label}</p><p className="mt-4 font-display text-3xl font-extrabold text-white">{number(item.value)}</p><p className="mt-2 text-xs text-slate-500">من {formatReportDate(startDate)} إلى {formatReportDate(endDate)}</p></CardContent></Card>)}</section>
    <Card className="border-sky-400/20 bg-sky-400/[.035] shadow-panel"><CardContent className="p-5"><div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between"><div><div className="flex items-center gap-2 text-sm font-bold text-sky-200"><GitCompareArrows className="h-4 w-4" />مقارنة الأداء المالي</div><p className="mt-1 text-sm text-slate-400">قارن الفترة الحالية بفترة أخرى للفرع نفسه، أو قارن فرعين خلال الفترة ذاتها.</p></div><div className="flex flex-wrap gap-2"><select aria-label="نوع المقارنة المالية" value={comparisonMode} onChange={(event) => setComparisonMode(event.target.value as "period" | "branch")} className={inputClass}><option className="bg-[#111823]" value="period">مقارنة بين فترتين</option>{canCompareBranches && <option className="bg-[#111823]" value="branch">مقارنة بين فرعين</option>}</select>{comparisonMode === "branch" ? <select aria-label="الفرع المقارن" value={alternateBranchId ?? ""} onChange={(event) => setComparisonSiteId(Number(event.target.value))} className={inputClass}>{(sitesQuery.data ?? []).filter((site) => site.id !== branchId).map((site) => <option className="bg-[#111823]" key={site.id} value={site.id}>{site.name}</option>)}</select> : <><input aria-label="تاريخ بداية المقارنة" type="date" value={comparisonStartDate} max={comparisonEndDate} onChange={(event) => setComparisonStartDate(event.target.value)} className={inputClass} dir="ltr" /><input aria-label="تاريخ نهاية المقارنة" type="date" value={comparisonEndDate} min={comparisonStartDate} onChange={(event) => setComparisonEndDate(event.target.value)} className={inputClass} dir="ltr" /></>}</div></div>{comparisonIsFetching && <p className="mt-4 text-xs font-bold text-sky-200">جارٍ احتساب المقارنة…</p>}{comparisonReport && report && <><ComparisonTable current={report.summary} compared={comparisonReport.summary} currentLabel={`${scopeName} — ${startDate} إلى ${endDate}`} comparisonLabel={comparisonScopeName} /><FinancialComparisonCharts current={report.summary} compared={comparisonReport.summary} currentLabel="النطاق الحالي" comparedLabel="خط الأساس" /></>}</CardContent></Card>
    {canManageBranding && <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="flex flex-col gap-4 p-5 lg:flex-row lg:items-center lg:justify-between"><div className="flex items-center gap-3">{brandingQuery.data?.logoUrl ? <img src={brandingQuery.data.logoUrl} alt="شعار الشركة في التقرير" className="h-14 w-14 rounded-xl border border-white/10 bg-white object-contain p-1" /> : <div className="grid h-14 w-14 place-items-center rounded-xl border border-dashed border-[#F5B800]/35 text-xs font-bold text-[#F5B800]">شعار</div>}<div><p className="font-bold text-white">هوية التقرير الرسمي</p><p className="mt-1 text-xs text-slate-400">يظهر اسم الشركة وشعارها في ملف PDF الرسمي فقط.</p></div></div><div className="flex flex-col gap-2 sm:flex-row"><input aria-label="اسم الشركة في التقرير" value={companyNameDraft} onChange={(event) => setCompanyNameDraft(event.target.value)} placeholder="اسم الشركة" className={inputClass} /><Button disabled={brandingMutation.isPending} onClick={saveCompanyName} variant="outline" className="border-white/10 text-white hover:bg-white/5 hover:text-white"><Save className="ml-2 h-4 w-4" />حفظ الاسم</Button><label className="inline-flex h-10 cursor-pointer items-center justify-center rounded-xl border border-[#F5B800]/40 px-3 text-sm font-bold text-[#F5B800] transition hover:bg-[#F5B800]/10"><ImagePlus className="ml-2 h-4 w-4" />رفع الشعار<input type="file" accept="image/png,image/jpeg,image/webp" className="sr-only" onChange={selectLogo} /></label></div></CardContent></Card>}
    <section aria-label="ملخص التحصيل حسب طريقة الدفع" className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{paymentSummary.length ? paymentSummary.map(([provider, amount]) => <Card className="border-white/8 bg-[#111823] shadow-panel" key={provider}><CardContent className="p-4"><p className="text-xs font-bold text-slate-400">{paymentProviderLabels[provider] ?? provider}</p><p className="mt-2 font-display text-2xl font-extrabold text-[#F5B800]">{number(amount)}</p><p className="mt-1 text-xs text-slate-500">إجمالي المبالغ المحصلة</p></CardContent></Card>) : <Card className="border-white/8 bg-[#111823] sm:col-span-2 xl:col-span-4"><CardContent className="p-4 text-sm text-slate-500">لا توجد دفعات مكتملة ضمن الفترة المحددة.</CardContent></Card>}</section>{paymentSummary.length > 0 && <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-5"><h2 className="font-bold text-white">توزيع التحصيل حسب طريقة الدفع</h2><p className="mt-1 text-xs text-slate-500">توزيع المبالغ المحصلة وفق الفلتر والفترة المحددين.</p><div className="mt-4 h-64"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={paymentSummary.map(([provider, amount]) => ({ name: paymentProviderLabels[provider] ?? provider, value: amount }))} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={88} label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}>{paymentSummary.map(([provider], index) => <Cell key={provider} fill={["#F5B800", "#38bdf8", "#34d399", "#fb7185"][index % 4]} />)}</Pie><Tooltip formatter={(value: number) => [number(value), "المبلغ"]} /></PieChart></ResponsiveContainer></div></CardContent></Card>}
    {report?.paymentDetails?.length ? <TableCard title="تفاصيل التحويلات والدفعات" columns={["الإيصال", "المبلغ", "الطريقة", "الحساب المحوِّل", "نوعه", "الحساب المستقبِل", "نوعه"]} rows={filteredReportPayments.map((payment) => [payment.paymentNo, number(payment.amount), paymentProviderLabels[payment.paymentMethod] ?? payment.paymentMethod, payment.transferFromAccount ?? "—", payment.transferFromType ?? "—", payment.transferToAccount ?? "—", payment.transferToType ?? "—"])} empty="لا توجد دفعات ضمن الفترة المحددة." /> : null}
    {scope === "all" && <TableCard title="التفصيل المالي حسب الفرع" columns={["الفرع", "الفوترة", "التحصيل", "الأرصدة المستحقة", "المصروفات", "صافي التدفق التشغيلي"]} rows={branchSummaries.map((branch) => [branch.branchName, number(branch.invoiced), number(branch.collected), number(branch.outstanding), number(branch.expenseTotal), number(branch.operatingProfit)])} empty="لا توجد بيانات مالية ضمن الفترة المحددة." />}
    <section className="grid gap-6 xl:grid-cols-2"><TableCard title="أداء المحصلين" columns={["المحصل", "عدد الدفعات", "التحصيل"]} rows={(report?.collectors ?? []).map((row) => [row.name, number(row.count, 0), number(row.amount)])} empty="لا توجد دفعات مكتملة في هذه الفترة." /><TableCard title="أعلى الأرصدة المستحقة" columns={scope === "all" ? ["الفرع", "المشترك", "الفاتورة", "المتبقي"] : ["المشترك", "الفاتورة", "المتبقي"]} rows={(report?.topDebtors ?? []).map((row) => scope === "all" ? [row.branchName ?? "—", row.subscriber, row.invoiceNo, number(row.balanceDue)] : [row.subscriber, row.invoiceNo, number(row.balanceDue)])} empty="لا توجد أرصدة مستحقة في الفترة المحددة." /></section>
    <OfficialPdfReport reportRef={pdfRef} report={filteredExportReport ?? report} scopeName={scopeName} companyName={brandingQuery.data?.companyName ?? "PowerHub"} logoUrl={brandingQuery.data?.logoUrl ?? null} comparison={comparisonReport ? { summary: comparisonReport.summary, label: comparisonScopeName } : null} paymentProvider={reportFilterLabel} sections={selectedReportSections} /><ReportPreviewDialog open={previewOpen} report={filteredExportReport ?? report} scopeName={scopeName} companyName={brandingQuery.data?.companyName ?? "PowerHub"} logoUrl={brandingQuery.data?.logoUrl ?? null} paymentProvider={reportFilterLabel} sections={selectedReportSections} zoom={previewZoom} onZoomChange={setPreviewZoom} onToggleSection={(section) => setSelectedReportSections((current) => current.includes(section) ? current.filter((item) => item !== section) : [...current, section])} startDate={startDate} endDate={endDate} onClose={() => setPreviewOpen(false)} onPrint={() => { setPreviewOpen(false); printReport(); }} onExcel={() => { setPreviewOpen(false); void downloadExcel(); }} onPdf={() => { setPreviewOpen(false); void downloadPdf(); }} />
  </div></DashboardLayout>;
}

function ExecutiveReportToolbar({ kind, label, scopeName, summary, collectionRate, onDaily, onMonthly, onCustom }: { kind: "daily" | "monthly" | "custom" ; label: string; scopeName: string; summary?: FinancialSummary; collectionRate: number; onDaily: () => void; onMonthly: () => void; onCustom: () => void }) {
  return <Card className="border-[#F5B800]/22 bg-[#111823] shadow-panel"><CardContent className="p-5"><div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between"><div><div className="flex items-center gap-2 text-sm font-bold text-[#F5B800]"><CalendarDays className="h-4 w-4" />التقارير التنفيذية</div><h2 className="mt-1 text-xl font-extrabold text-white">{label}</h2><p className="mt-2 text-sm text-slate-400">{scopeName} — ملخص موجز لمتابعة الفوترة والتحصيل والأرصدة المستحقة.</p></div><div className="flex flex-wrap gap-2"><Button onClick={onDaily} variant={kind === "daily" ? "default" : "outline"} className={kind === "daily" ? "bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]" : "border-white/10 text-white hover:bg-white/5 hover:text-white"}>تقرير اليوم</Button><Button onClick={onMonthly} variant={kind === "monthly" ? "default" : "outline"} className={kind === "monthly" ? "bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]" : "border-white/10 text-white hover:bg-white/5 hover:text-white"}>تقرير الشهر</Button><Button onClick={onCustom} variant={kind === "custom" ? "default" : "outline"} className={kind === "custom" ? "bg-[#F5B800] font-bold text-[#0D1117] hover:bg-[#ffd23f]" : "border-white/10 text-white hover:bg-white/5 hover:text-white"}>نطاق مخصص</Button></div></div><div className="mt-5 grid gap-3 sm:grid-cols-3"><div className="rounded-xl border border-white/8 bg-[#0D1117]/35 p-3"><p className="text-xs text-slate-400">نسبة التحصيل</p><p className={`mt-2 font-display text-2xl font-extrabold ${collectionRate < 70 && summary?.invoiced ? "text-rose-300" : "text-emerald-300"}`}>{number(collectionRate, 1)}%</p></div><div className="rounded-xl border border-white/8 bg-[#0D1117]/35 p-3"><p className="text-xs text-slate-400">صافي التدفق التشغيلي</p><p className="mt-2 font-display text-2xl font-extrabold text-white">{number((summary?.collected ?? 0) - (summary?.expenseTotal ?? 0))}</p></div><div className="rounded-xl border border-white/8 bg-[#0D1117]/35 p-3"><p className="text-xs text-slate-400">الأرصدة المستحقة ضمن التقرير</p><p className="mt-2 font-display text-2xl font-extrabold text-rose-200">{number(summary?.outstanding)}</p></div></div></CardContent></Card>;
}

function ReportRangePresets({ onSelect }: { onSelect: (value: string) => void }) { return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-bold text-white">تصفية زمنية متقدمة</p><p className="mt-1 text-xs leading-5 text-slate-500">طبّق نطاقاً سريعاً ثم عدّل تاريخ البداية والنهاية يدوياً عند الحاجة.</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => onSelect("today")} className="border-white/10 text-white hover:bg-white/5 hover:text-white">اليوم</Button><Button size="sm" variant="outline" onClick={() => onSelect("month")} className="border-white/10 text-white hover:bg-white/5 hover:text-white">الشهر الحالي</Button><Button size="sm" variant="outline" onClick={() => onSelect("last30")} className="border-white/10 text-white hover:bg-white/5 hover:text-white">آخر 30 يوماً</Button><Button size="sm" variant="outline" onClick={() => onSelect("quarter")} className="border-white/10 text-white hover:bg-white/5 hover:text-white">الربع الحالي</Button></div></CardContent></Card>; }

function FinancialAccessScope({ role, global }: { role?: string; global: boolean }) { const roleLabel: Record<string, string> = { owner: "المالك", manager: "المدير", accountant: "المحاسب", collector: "المحصل", viewer: "المشاهد" }; return <Card className={global ? "border-sky-400/20 bg-sky-400/[.035]" : "border-white/8 bg-[#111823]"}><CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-bold text-white">نطاق صلاحية البيانات المالية</p><p className="mt-1 text-sm leading-6 text-slate-400">{global ? "يمكن لهذا الحساب عرض التقرير المجمّع ومقارنة الأفرع المصرح بها، مع استمرار فرض العزل على مستوى المستأجر." : "هذا الحساب مقيد بالفرع المعيّن له؛ لا يمكنه فتح التقرير المجمّع أو مقارنة بيانات فروع أخرى."}</p></div><Badge className={global ? "w-fit bg-sky-400/10 text-sky-200" : "w-fit bg-white/5 text-slate-300"}>{roleLabel[role ?? ""] ?? "حساب تشغيل"} · {global ? "صلاحية جميع الأفرع" : "صلاحية فرع محدد"}</Badge></CardContent></Card>; }

function ComparisonTable({ current, compared, currentLabel, comparisonLabel }: { current: FinancialSummary; compared: FinancialSummary; currentLabel: string; comparisonLabel: string }) { return <div className="mt-5 overflow-x-auto"><table className="w-full min-w-[680px] text-sm"><thead className="text-right text-xs text-slate-400"><tr><th className="pb-3">المؤشر</th><th className="pb-3">الحالي</th><th className="pb-3">المقارن</th><th className="pb-3">الفرق</th><th className="pb-3">نسبة التغير</th></tr></thead><tbody>{reportMetrics.map((metric) => { const currentValue = current[metric.key]; const comparedValue = compared[metric.key]; const change = difference(currentValue, comparedValue); const positive = change.amount >= 0; return <tr className="border-t border-white/8" key={metric.key}><td className="py-3 font-bold text-white">{metric.label}</td><td className="py-3 text-slate-200">{number(currentValue)}</td><td className="py-3 text-slate-400">{number(comparedValue)}</td><td className={`py-3 font-bold ${positive ? "text-emerald-300" : "text-rose-300"}`}>{positive ? <ArrowUpRight className="ml-1 inline h-3.5 w-3.5" /> : <ArrowDownLeft className="ml-1 inline h-3.5 w-3.5" />}{number(change.amount)}</td><td className={`py-3 font-bold ${positive ? "text-emerald-300" : "text-rose-300"}`}>{change.percent === null ? "جديد" : `${number(change.percent, 1)}%`}</td></tr>; })}</tbody></table><div className="mt-3 grid gap-2 text-xs text-slate-500 sm:grid-cols-2"><p><strong className="text-slate-300">الحالي:</strong> {currentLabel}</p><p><strong className="text-slate-300">خط الأساس:</strong> {comparisonLabel}</p></div></div>; }

function FinancialComparisonCharts({ current, compared, currentLabel, comparedLabel }: { current: FinancialSummary; compared: FinancialSummary; currentLabel: string; comparedLabel: string }) {
  const data = reportMetrics.map((metric) => { const change = difference(current[metric.key], compared[metric.key]); return { label: metric.label, current: current[metric.key], compared: compared[metric.key], changePercent: change.percent ?? 100, direction: change.amount >= 0 ? "ارتفاع" : "انخفاض" }; });
  return <section className="mt-7 grid gap-5 xl:grid-cols-2"><div className="rounded-2xl border border-white/8 bg-[#0D1117]/35 p-4"><div><h3 className="font-bold text-white">رسم المقارنة المالي</h3><p className="mt-1 text-xs text-slate-500">مرّر المؤشر فوق الأعمدة لقراءة قيمة كل نطاق بدقة.</p></div><div aria-label="رسم أعمدة المقارنة المالية" className="mt-4 h-72"><ResponsiveContainer width="100%" height="100%"><BarChart data={data} margin={{ top: 12, right: 6, left: -18, bottom: 8 }}><CartesianGrid stroke="#ffffff12" vertical={false} /><XAxis dataKey="label" stroke="#94a3b8" fontSize={10} interval={0} tick={{ width: 62 }} /><YAxis stroke="#64748b" fontSize={11} /><Tooltip contentStyle={{ background: "#111823", border: "1px solid #ffffff1a", borderRadius: 12, direction: "rtl" }} formatter={(value: number, name: string) => [number(value), name === "current" ? currentLabel : comparedLabel]} /><Legend formatter={(value) => value === "current" ? currentLabel : comparedLabel} /><Bar name="current" dataKey="current" fill="#F5B800" radius={[5, 5, 0, 0]} /><Bar name="compared" dataKey="compared" fill="#38bdf8" radius={[5, 5, 0, 0]} /></BarChart></ResponsiveContainer></div></div><div className="rounded-2xl border border-white/8 bg-[#0D1117]/35 p-4"><div><h3 className="font-bold text-white">نسبة التغير حسب المؤشر</h3><p className="mt-1 text-xs text-slate-500">القيم الموجبة تعني ارتفاعاً مقارنة بخط الأساس، والسالبة تعني انخفاضاً.</p></div><div aria-label="رسم نسبة التغير المالي" className="mt-4 h-72"><ResponsiveContainer width="100%" height="100%"><BarChart data={data} layout="vertical" margin={{ top: 8, right: 16, left: 18, bottom: 8 }}><CartesianGrid stroke="#ffffff12" horizontal={false} /><XAxis type="number" stroke="#64748b" fontSize={11} tickFormatter={(value) => `${value}%`} /><YAxis type="category" dataKey="label" stroke="#94a3b8" fontSize={11} width={92} /><Tooltip contentStyle={{ background: "#111823", border: "1px solid #ffffff1a", borderRadius: 12, direction: "rtl" }} formatter={(value: number) => [`${number(value, 1)}%`, "التغير"]} /><Bar dataKey="changePercent" radius={[0, 5, 5, 0]}>{data.map((entry) => <Cell key={entry.label} fill={entry.direction === "ارتفاع" ? "#34d399" : "#fb7185"} />)}</Bar></BarChart></ResponsiveContainer></div></div></section>;
}

function ReportPreviewDialog({ open, report, scopeName, companyName, logoUrl, paymentProvider, sections, zoom, onZoomChange, onToggleSection, startDate, endDate, onClose, onPrint, onExcel, onPdf }: { open: boolean; report?: FinancialReport | null; scopeName: string; companyName: string; logoUrl: string | null; paymentProvider: string; sections: ReportSection[]; zoom: number; onZoomChange: (value: number) => void; onToggleSection: (section: ReportSection) => void; startDate: string; endDate: string; onClose: () => void; onPrint: () => void; onExcel: () => void; onPdf: () => void }) {
  if (!report) return null;
  const payments = report.paymentDetails ?? [];
  return <Dialog open={open} onOpenChange={(value) => !value && onClose()}><DialogContent className="max-h-[90vh] max-w-5xl overflow-y-auto border-white/10 bg-[#111823] text-white"><DialogHeader><DialogTitle>معاينة التقرير قبل الطباعة أو التصدير</DialogTitle></DialogHeader>
    <div className="rounded-xl bg-white p-6 text-right text-[#0D1117] transition-transform" style={{ transform: "scale(" + (zoom / 100) + ")", transformOrigin: "top center", marginBottom: ((zoom - 100) * 1.8) + "px" }} dir="rtl">
      <div className="flex items-start justify-between border-b-4 border-[#F5B800] pb-4">{logoUrl ? <img src={logoUrl} alt="شعار الشركة" className="h-16 w-16 object-contain" /> : <div className="grid h-16 w-16 place-items-center rounded-lg bg-[#0D1117] font-bold text-[#F5B800]">PowerHub</div>}<div><p className="text-xs font-bold text-[#A17400]">{companyName}</p><h2 className="mt-1 text-2xl font-extrabold">تقرير مالي</h2><p className="mt-1 text-xs text-[#647080]">{scopeName} · {formatReportPeriod(startDate, endDate)} · {paymentProvider}</p></div></div>
      {sections.includes("summary") && <section className="mt-5"><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{reportMetrics.slice(0, 4).map((metric) => <div className="rounded-lg border border-[#E4E7EB] p-3" key={metric.key}><p className="text-xs text-[#647080]">{metric.label}</p><p className="mt-1 font-bold">{number(report.summary[metric.key])}</p></div>)}</div></section>}
      {sections.includes("branches") && (report.branchSummaries ?? []).length > 0 && <section className="mt-6"><h3 className="font-extrabold">تفصيل الأفرع</h3><div className="mt-3 overflow-x-auto"><table className="w-full text-xs"><thead><tr className="border-b border-[#E4E7EB]"><th className="p-2">الفرع</th><th className="p-2">الفوترة</th><th className="p-2">التحصيل</th><th className="p-2">الأرصدة المستحقة</th><th className="p-2">المصروفات</th><th className="p-2">صافي التدفق التشغيلي</th></tr></thead><tbody>{(report.branchSummaries ?? []).map((branch) => <tr className="border-b border-[#E4E7EB]" key={branch.siteId}><td className="p-2 font-bold">{branch.branchName}</td><td className="p-2">{number(branch.invoiced)}</td><td className="p-2">{number(branch.collected)}</td><td className="p-2">{number(branch.outstanding)}</td><td className="p-2">{number(branch.expenseTotal)}</td><td className="p-2">{number(branch.operatingProfit)}</td></tr>)}</tbody></table></div></section>}
      {sections.includes("collectors") && <section className="mt-6"><h3 className="font-extrabold">أداء المحصلين</h3>{(report.collectors ?? []).length ? <div className="mt-3 overflow-x-auto"><table className="w-full text-xs"><thead><tr className="border-b border-[#E4E7EB]"><th className="p-2">المحصل</th><th className="p-2">عدد العمليات</th><th className="p-2">قيمة التحصيل</th></tr></thead><tbody>{(report.collectors ?? []).map((collector) => <tr className="border-b border-[#E4E7EB]" key={collector.name}><td className="p-2 font-bold">{collector.name}</td><td className="p-2">{number(collector.count, 0)}</td><td className="p-2">{number(collector.amount)}</td></tr>)}</tbody></table></div> : <p className="mt-2 text-sm text-[#647080]">لا توجد تحصيلات مكتملة ضمن الفترة.</p>}</section>}
      {sections.includes("payments") && <section className="mt-6"><h3 className="font-extrabold">تفاصيل الدفعات والتحويلات</h3>{payments.length ? <div className="mt-3 overflow-x-auto"><table className="w-full text-xs"><thead><tr className="border-b border-[#E4E7EB]"><th className="p-2">الإيصال</th><th className="p-2">المبلغ</th><th className="p-2">طريقة الدفع</th><th className="p-2">الحساب المحوِّل</th><th className="p-2">الحساب المستقبِل</th><th className="p-2">التاريخ</th></tr></thead><tbody>{payments.map((payment) => <tr className="border-b border-[#E4E7EB]" key={payment.paymentNo}><td className="p-2 font-bold">{payment.paymentNo}</td><td className="p-2">{number(payment.amount)}</td><td className="p-2">{paymentProviderLabels[payment.paymentMethod] ?? payment.paymentMethod}</td><td className="p-2">{payment.transferFromAccount ?? "—"}</td><td className="p-2">{payment.transferToAccount ?? "—"}</td><td className="p-2">{formatReportDate(payment.paidAt)}</td></tr>)}</tbody></table></div> : <p className="mt-2 text-sm text-[#647080]">لا توجد دفعات مكتملة ضمن الفلاتر الحالية.</p>}</section>}
    </div>
    <div className="rounded-lg border border-white/10 bg-white/[0.03] p-3"><p className="mb-2 text-sm font-bold">الحقول الظاهرة في التقرير</p><div className="flex flex-wrap gap-3">{(Object.keys(reportSectionLabels) as ReportSection[]).map((section) => <label className="flex items-center gap-2 text-sm" key={section}><input type="checkbox" checked={sections.includes(section)} onChange={() => onToggleSection(section)} />{reportSectionLabels[section]}</label>)}</div></div>
    <div className="flex flex-wrap items-center justify-end gap-2 pt-2"><Button onClick={() => onZoomChange(Math.max(70, zoom - 10))} variant="outline" className="border-white/10 text-white">تصغير</Button><span className="min-w-14 text-center text-sm text-slate-300">{zoom}%</span><Button onClick={() => onZoomChange(Math.min(140, zoom + 10))} variant="outline" className="border-white/10 text-white">تكبير</Button><Button onClick={() => onZoomChange(100)} variant="outline" className="border-white/10 text-white">إعادة ضبط</Button><Button onClick={onPrint} className="bg-sky-500 font-bold text-white hover:bg-sky-400">طباعة التقرير</Button><Button onClick={onExcel} className="bg-emerald-500 font-bold text-white hover:bg-emerald-400">تصدير Excel</Button><Button onClick={onPdf} variant="outline" className="border-rose-400/35 text-rose-200 hover:bg-rose-400/10">تصدير PDF</Button><Button onClick={onClose} variant="outline" className="border-white/10 text-white hover:bg-white/5">إلغاء</Button></div>
  </DialogContent></Dialog>;
}

function OfficialPdfReport({ reportRef, report, scopeName, companyName, logoUrl, comparison, paymentProvider, sections }: { reportRef: React.RefObject<HTMLDivElement | null>; report?: FinancialReport; scopeName: string; companyName: string; logoUrl: string | null; comparison: { summary: FinancialSummary; label: string } | null; paymentProvider: string; sections: ReportSection[] }) {
  if (!report) return null;
  const paymentDetails = report.paymentDetails ?? [];
  const branchSummaries = report.branchSummaries ?? [];
  return <div ref={reportRef} aria-hidden className="pointer-events-none fixed left-[-9999px] top-0 w-[760px] bg-white p-10 text-right text-[#0D1117]" dir="rtl">
    <header className="flex items-center justify-between border-b-4 border-[#F5B800] pb-6">{logoUrl ? <img src={logoUrl} alt="شعار الشركة" className="h-20 w-20 object-contain" /> : <div className="grid h-20 w-20 place-items-center rounded-xl bg-[#0D1117] font-bold text-[#F5B800]">PowerHub</div>}<div><p className="text-sm font-bold text-[#A17400]">POWERHUB — إدارة الطاقة بذكاء</p><h1 className="mt-2 text-3xl font-extrabold">تقرير مالي رسمي</h1><p className="mt-2 text-lg font-bold">{companyName}</p></div></header>
    <section className="mt-7 grid grid-cols-2 gap-4 rounded-xl bg-[#F5F6F8] p-5 text-sm"><p><strong>نطاق التقرير:</strong> {scopeName}</p><p><strong>الفترة:</strong> {formatReportPeriod(report.range.startDate, report.range.endDate)}</p><p><strong>طريقة الدفع:</strong> {paymentProvider}</p><p><strong>تاريخ الإصدار:</strong> {formatReportDate(new Date())}</p><p><strong>حالة الوثيقة:</strong> صادر إلكترونيًا</p></section>
    {sections.includes("summary") && <section className="mt-7"><h2 className="border-r-4 border-[#F5B800] pr-3 text-lg font-extrabold">الملخص المالي</h2><div className="mt-4 grid grid-cols-2 gap-3">{reportMetrics.map((metric) => <div key={metric.key} className="rounded-lg border border-[#E4E7EB] p-4"><p className="text-xs text-[#647080]">{metric.label}</p><p className="mt-2 text-xl font-extrabold">{number(report.summary[metric.key])}</p></div>)}</div></section>}
    {sections.includes("branches") && branchSummaries.length > 0 && <section className="mt-7"><h2 className="text-lg font-extrabold">تفصيل الأفرع</h2><table className="mt-4 w-full border-collapse text-xs"><thead><tr>{["الفرع","الفوترة","التحصيل","الأرصدة المستحقة","المصروفات","صافي التدفق التشغيلي"].map((label) => <th key={label} className="border border-[#D9DDE3] bg-[#0D1117] p-2 text-white">{label}</th>)}</tr></thead><tbody>{branchSummaries.map((branch) => <tr key={branch.siteId}>{[branch.branchName, number(branch.invoiced), number(branch.collected), number(branch.outstanding), number(branch.expenseTotal), number(branch.operatingProfit)].map((value, index) => <td key={index} className="border border-[#D9DDE3] p-2">{value}</td>)}</tr>)}</tbody></table></section>}
    {sections.includes("collectors") && <section className="mt-7"><h2 className="text-lg font-extrabold">أداء المحصلين</h2><table className="mt-4 w-full border-collapse text-sm"><thead><tr>{["المحصل","عدد العمليات","قيمة التحصيل"].map((label) => <th key={label} className="border border-[#D9DDE3] bg-[#0D1117] p-2 text-white">{label}</th>)}</tr></thead><tbody>{(report.collectors ?? []).length ? (report.collectors ?? []).map((collector) => <tr key={collector.name}><td className="border border-[#D9DDE3] p-2">{collector.name}</td><td className="border border-[#D9DDE3] p-2">{number(collector.count, 0)}</td><td className="border border-[#D9DDE3] p-2">{number(collector.amount)}</td></tr>) : <tr><td colSpan={3} className="border border-[#D9DDE3] p-3 text-center text-[#647080]">لا توجد تحصيلات مكتملة ضمن الفترة.</td></tr>}</tbody></table></section>}
    {sections.includes("payments") && <section className="mt-7"><h2 className="text-lg font-extrabold">تفاصيل الدفعات والتحويلات</h2><table className="mt-4 w-full border-collapse text-[10px]"><thead><tr>{["الإيصال","المبلغ","طريقة الدفع","الحساب المحوِّل","الحساب المستقبِل","التاريخ"].map((label) => <th key={label} className="border border-[#D9DDE3] bg-[#0D1117] p-2 text-white">{label}</th>)}</tr></thead><tbody>{paymentDetails.length ? paymentDetails.map((payment) => <tr key={payment.paymentNo}><td className="border border-[#D9DDE3] p-2">{payment.paymentNo}</td><td className="border border-[#D9DDE3] p-2">{number(payment.amount)}</td><td className="border border-[#D9DDE3] p-2">{paymentProviderLabels[payment.paymentMethod] ?? payment.paymentMethod}</td><td className="border border-[#D9DDE3] p-2">{payment.transferFromAccount ?? "—"}</td><td className="border border-[#D9DDE3] p-2">{payment.transferToAccount ?? "—"}</td><td className="border border-[#D9DDE3] p-2">{formatReportDate(payment.paidAt)}</td></tr>) : <tr><td colSpan={6} className="border border-[#D9DDE3] p-3 text-center text-[#647080]">لا توجد دفعات مكتملة ضمن الفلاتر الحالية.</td></tr>}</tbody></table></section>}
    {comparison ? <section className="mt-7 border-t border-[#E4E7EB] pt-5"><h2 className="text-lg font-extrabold">ملخص المقارنة</h2><p className="mt-2 text-sm text-[#647080]">خط الأساس: {comparison.label}</p><div className="mt-3 grid grid-cols-2 gap-3 text-sm">{reportMetrics.slice(0, 4).map((metric) => { const change = difference(report.summary[metric.key], comparison.summary[metric.key]); return <p key={metric.key}><strong>{metric.label}:</strong> {number(change.amount)} {change.percent === null ? "(جديد)" : "(" + number(change.percent, 1) + "%)"}</p>; })}</div></section> : null}
    <footer className="mt-10 border-t border-[#E4E7EB] pt-4 text-center text-xs text-[#647080]">هذا التقرير صادر من نظام PowerHub ويعرض بيانات النطاق المحدد فقط.</footer>
  </div>;
}

function TableCard({ title, columns, rows, empty }: { title: string; columns: string[]; rows: string[][]; empty: string }) { return <Card className="border-white/8 bg-[#111823] shadow-panel"><CardContent className="p-0"><div className="border-b border-white/8 px-5 py-4"><h2 className="font-bold text-white">{title}</h2></div><div className="overflow-x-auto p-5">{rows.length ? <table className="w-full min-w-[380px] text-sm"><thead className="text-right text-xs text-slate-500"><tr>{columns.map((column) => <th className="pb-3" key={column}>{column}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr className="border-t border-white/7" key={`${row[0]}-${index}`}>{row.map((cell, cellIndex) => <td className={cellIndex === 0 ? "py-3 font-bold text-white" : "py-3 text-slate-300"} key={cellIndex}>{cell}</td>)}</tr>)}</tbody></table> : <p className="rounded-xl border border-dashed border-white/10 px-4 py-10 text-center text-sm text-slate-500">{empty}</p>}</div></CardContent></Card>; }
